//! 🎟️ Actual typed read close and source refusal preserve independent CPU, physical stock and identity.
use semio_framework_value_read::{ReadOwnershipRegistry,RetainedCloneGrant as G,RetainedCloneProgress as P,RetainedCloneStep as S,ErasedSnapshotRetirement,ValueRefusalKind,retirement::arc_custody::SharedControlledRetirement};
use semio_framework_value_testing_allocator::{observe_retirement_allocations,refuse_one_allocation_on_this_thread};
use std::sync::Arc;
fn law()->serde_json::Value{let value:serde_json::Value=serde_json::from_str(include_str!("../case.json")).unwrap();let schema:serde_json::Value=serde_json::from_str(include_str!("../case.schema.json")).unwrap();for(k,v)in value.as_object().unwrap(){assert_eq!(&schema["properties"][k]["const"],v);}value}
#[test]
fn real_read_alias_child_handoff_and_empty_header_have_distinct_quantum_one_work(){
 let row=law();let q=G{maximum_items:1,maximum_depth:128,maximum_copy_bytes:16777216,maximum_capacity_bytes:16777216,maximum_release_bytes:16777216};
 let(registry,_)=ReadOwnershipRegistry::<u64>::admit(G{maximum_capacity_bytes:ReadOwnershipRegistry::<u64>::constructor_capacity_bytes(),..q}).unwrap();let(read,_)=registry.try_issue(Arc::new(19),q).unwrap_or_else(|_|panic!("real preborn read"));let mut read=read;let id=read.id();let mut spent=P::default();let mut work=0u64;
 let(turn,heap)=observe_retirement_allocations(||read.close_step(G{maximum_items:0,..q}));assert_eq!(turn.work,row["deniedWork"].as_u64().unwrap());assert_eq!(turn.result.unwrap().progress(),P::default());assert_eq!(heap,(0,0));assert_eq!(*read.get(),19);
 for _ in 0..4{let(turn,heap)=observe_retirement_allocations(||read.close_step(q));assert_eq!(turn.work,1);let p=turn.result.unwrap().progress();assert!(p.fits(q));assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));assert_eq!(heap,(0,0));spent=spent.checked_add(p).unwrap();work+=turn.work;assert!(spent.fits(G{maximum_items:row["stock"]["items"].as_u64().unwrap()as usize,..q})&&work<=row["stock"]["fuel"].as_u64().unwrap());assert!(registry.contains(id).unwrap());}
 assert!(read.terminal_is_empty());let(turn,heap)=observe_retirement_allocations(||read.close_step(q));assert_eq!(turn.work,row["cachedWork"].as_u64().unwrap());assert!(matches!(turn.result.unwrap(),S::Complete(p)if p==P::default()));assert_eq!(heap,(0,0));
 let mut close=SharedControlledRetirement::lease(registry);
 for _ in 0..row["maximumTurns"].as_u64().unwrap(){if close.terminal_is_empty(){break}let g=G{maximum_items:1,maximum_copy_bytes:q.maximum_copy_bytes-spent.copied_bytes,maximum_capacity_bytes:q.maximum_capacity_bytes-spent.retained_capacity_bytes,maximum_release_bytes:q.maximum_release_bytes-spent.released_bytes,..q};let(result,heap)=observe_retirement_allocations(||close.step(g));let actual=close.last_turn_work();let p=result.unwrap().progress();assert!(actual<=1);assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));spent=spent.checked_add(p).unwrap();work+=actual;assert!(spent.fits(G{maximum_items:row["stock"]["items"].as_u64().unwrap()as usize,..q})&&work<=row["stock"]["fuel"].as_u64().unwrap());}
 assert!(close.terminal_is_empty());assert_eq!(observe_retirement_allocations(||drop((read,close))).1,(0,0));
}
#[test]
fn canonical_borrowed_source_null_retains_the_same_read_and_direct_attempt_work(){
 let row=law();let stock=G{maximum_items:row["stock"]["items"].as_u64().unwrap()as usize,maximum_depth:128,maximum_copy_bytes:16777216,maximum_capacity_bytes:16777216,maximum_release_bytes:16777216};let mut spent=P::default();let mut work=0u64;
 let(registry,_)=ReadOwnershipRegistry::<String>::admit(G{maximum_items:1,maximum_capacity_bytes:ReadOwnershipRegistry::<String>::constructor_capacity_bytes(),..stock}).unwrap();let root=Arc::new("owned λ".to_owned());let pointer=Arc::as_ptr(&root);let(read,_)=registry.try_issue(root,G{maximum_items:1,..stock}).unwrap_or_else(|_|panic!("preborn typed read"));let mut admission=read.source_admission().unwrap_or_else(|_|panic!("actual original read"));
 let(turn,heap)=observe_retirement_allocations(||admission.advance(G{maximum_items:0,..stock}));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),P::default());assert_eq!(heap,(0,0));
 let((turn,attempts),heap)=observe_retirement_allocations(||refuse_one_allocation_on_this_thread(||admission.advance(G{maximum_items:1,..stock})));assert_eq!(attempts,1);assert_eq!(turn.work,1);let error=turn.result.unwrap_err();work+=turn.work;assert_eq!(error.kind,ValueRefusalKind::AllocationFailed);assert_eq!(heap,(0,0));let mut returned=None;
 for _ in 0..row["maximumTurns"].as_u64().unwrap(){if admission.terminal_is_empty(){break}let g=G{maximum_items:1,maximum_copy_bytes:stock.maximum_copy_bytes-spent.copied_bytes,maximum_capacity_bytes:stock.maximum_capacity_bytes-spent.retained_capacity_bytes,maximum_release_bytes:stock.maximum_release_bytes-spent.released_bytes,..stock};let(turn,heap)=observe_retirement_allocations(||admission.return_inputs(&mut returned,g));work+=turn.work;let p=turn.result.unwrap().progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));spent=spent.checked_add(p).unwrap();assert!(spent.fits(stock)&&work<=row["stock"]["fuel"].as_u64().unwrap());}
 assert!(admission.terminal_is_empty());let(mut capsule,())=returned.unwrap();assert_eq!(capsule.get()as*const String,pointer);assert_eq!(serde_json::to_value(capsule.get()).unwrap(),serde_json::json!("owned λ"));let mut read=None;let g=G{maximum_items:1,..stock};let(turn,heap)=observe_retirement_allocations(||capsule.return_read(&mut read,g));work+=turn.work;let p=turn.result.unwrap().progress();assert_eq!(heap,(0,0));spent=spent.checked_add(p).unwrap();let mut read=read.unwrap();
 for _ in 0..row["maximumTurns"].as_u64().unwrap(){if read.terminal_is_empty(){break}let g=G{maximum_items:1,maximum_copy_bytes:stock.maximum_copy_bytes-spent.copied_bytes,maximum_capacity_bytes:stock.maximum_capacity_bytes-spent.retained_capacity_bytes,maximum_release_bytes:stock.maximum_release_bytes-spent.released_bytes,..stock};let(turn,heap)=observe_retirement_allocations(||read.close_step(g));work+=turn.work;let p=turn.result.unwrap().progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));spent=spent.checked_add(p).unwrap();assert!(spent.fits(stock)&&work<=row["stock"]["fuel"].as_u64().unwrap());}assert!(read.terminal_is_empty());
 let mut close=SharedControlledRetirement::lease(registry);for _ in 0..row["maximumTurns"].as_u64().unwrap(){if close.terminal_is_empty(){break}let g=G{maximum_items:1,maximum_copy_bytes:stock.maximum_copy_bytes-spent.copied_bytes,maximum_capacity_bytes:stock.maximum_capacity_bytes-spent.retained_capacity_bytes,maximum_release_bytes:stock.maximum_release_bytes-spent.released_bytes,..stock};let(result,heap)=observe_retirement_allocations(||close.step(g));work+=close.last_turn_work();let p=result.unwrap().progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));spent=spent.checked_add(p).unwrap();assert!(spent.fits(stock)&&work<=row["stock"]["fuel"].as_u64().unwrap());}assert!(close.terminal_is_empty());assert_eq!(observe_retirement_allocations(||drop((read,close,capsule,admission))).1,(0,0));
}
